import{_ as o,o as c,c as t,a2 as d}from"./chunks/framework.CvydjLy7.js";const m=JSON.parse('{"title":"10.14 小结与下一步","description":"","frontmatter":{"title":"10.14 小结与下一步"},"headers":[],"relativePath":"ch10/14.md","filePath":"ch10/14.md","lastUpdated":1789497795000}'),r={name:"ch10/14.md"};function i(n,e,a,s,l,g){return c(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="_10-14-小结与下一步" tabindex="-1">10.14 小结与下一步 <a class="header-anchor" href="#_10-14-小结与下一步" aria-label="Permalink to &quot;10.14 小结与下一步&quot;">​</a></h1><p>这一篇做的事：</p><ul><li>Actuator 的默认暴露面（Web 只有 <code>health</code>）、为什么 <code>*</code> 在 YAML 里要加引号，以及<strong>未暴露端点返回 404 而非 403</strong></li><li><strong>4.x 的三处搬迁</strong>：<code>HealthIndicator</code> → <code>org.springframework.boot.health.contributor</code>（独立模块 <code>spring-boot-health</code>）、<code>MeterRegistryCustomizer</code> → <code>org.springframework.boot.micrometer.metrics.autoconfigure</code>、<code>EndpointRequest</code> → <code>org.springframework.boot.security.autoconfigure.actuate.web.servlet</code>（旧位置已删除）</li><li>健康检查：实测的 7 个内置组件（含 <strong>4.0 新增的 <code>ssl</code></strong>）、自定义 <code>HealthIndicator</code>、组件名 = bean 名去后缀、<code>show-details</code> 与 <code>show-components</code> 的分工</li><li>存活与就绪探针：<strong>liveness 绝不能带外部依赖</strong>、组状态按组件聚合（实测是 <code>DOWN</code> 不是 <code>OUT_OF_SERVICE</code>）、<code>503</code> 是接负载均衡的关键</li><li><code>info</code> 端点的坑：<strong>不打开 <code>management.info.env.enabled</code>，<code>info.app.*</code> 根本不会出现</strong></li><li>指标的写法：注入注册表而非用静态方法、低基数标签、<strong>同名不同标签会多出 0 值时间线</strong>、<code>Gauge</code> 传取值函数、<code>MeterBinder</code> 绑定他人数据、公共标签的代价</li><li>Prometheus 端的命名转换规则（点→下划线、<code>_total</code>、<code>_seconds</code>、<code>_bucket</code>），实测 913 行 / 81 个 <code>TYPE</code></li><li><strong>测试环境里真实指标导出被 <code>spring-boot-micrometer-metrics-test</code> 换成了 <code>SimpleMeterRegistry</code></strong>，<code>spring.test.metrics.export</code> 默认 <code>false</code></li><li><code>loggers</code> 端点：<code>configuredLevel</code> 与 <code>effectiveLevel</code> 的差异、<code>null</code> 时字段整个消失、分组整组调级、<strong>隐藏 logger 的下划线前缀</strong>（<code>LogDelegateFactory.getHiddenLog</code>，<code>since 5.3.5</code>）</li><li>自定义端点：<code>@Endpoint</code> 与 <code>@ReadOperation</code> / <code>@WriteOperation</code>、参数只能是简单类型、<code>@Endpoint</code> 与 <code>@WebEndpoint</code> 的区别</li><li>可观测性：<code>management.observations.*</code> 属性、注解观测默认关闭、<strong><code>management.tracing.enabled</code> 已废弃且为 error 级</strong>、追踪桥接模块的 4.x 坐标</li><li>端点安全的三道防线：收敛暴露面、<code>when-authorized</code> + 角色、独立管理端口</li></ul><p>工程侧新增 <code>activity-server-observability</code>，22 个用例、6.9 秒全绿，覆盖健康检查、指标、四个端点与隐藏 logger 的行为。</p><p>到这里，一个能跑、能测、能观测的后端已经完整了。但还有个问题没回答：它现在只能在你本机的 IDE 里跑，<strong>怎么变成一个可以交出去的东西</strong>？</p><p>下一篇处理打包与部署：可执行 jar 的内部结构、分层 jar 与镜像的关系、容器化时那两个必须注意的镜像构建细节、原生镜像的取舍，以及为什么“打成 jar 就能跑”和“能在生产上跑”之间还差一批配置。</p>',6)])])}const _=o(r,[["render",i]]);export{m as __pageData,_ as default};
